UPDATE picture
url = #{picture.url}, name = #{picture.name}, introduction = #{picture.introduction}, category = #{picture.category}, tags = #{picture.tags}, picSize = #{picture.picSize}, picWidth = #{picture.picWidth}, picHeight = #{picture.picHeight}, picScale = #{picture.picScale}, picFormat = #{picture.picFormat}, userId = #{picture.userId}, thumbnailUrl = #{picture.thumbnailUrl}, createTime = #{picture.createTime}, editTime = #{picture.editTime}, updateTime = #{picture.updateTime}, reviewStatus = #{picture.reviewStatus}, reviewMessage = #{picture.reviewMessage}, reviewerId = #{picture.reviewerId}, reviewTime = #{picture.reviewTime}, picColor = #{picture.picColor}, isDelete = #{picture.isDelete}
WHERE id = #{picture.id} AND isDelete = 0
